// ── Helper to fill in defaults & derive surface & execution steps ─────────────────
type PartialDrill = Partial<FootballDrill> & { id: string; name: string; family: DrillFamily };

function deriveSurfaces(p: PartialDrill): ContactSurface[] {
  if (p.contactSurface && p.contactSurface.length > 0) return p.contactSurface;
  const text = (p.name + ' ' + (p.tags?.join(' ') || '') + ' ' + (p.technicalObjective || '')).toLowerCase();
  const res: ContactSurface[] = [];
  if (text.includes('interior')) res.push('interior');
  if (text.includes('empeine') || text.includes('volea') || text.includes('remate') || text.includes('potencia')) res.push('empeine');
  if (text.includes('exterior') || text.includes('hook') || text.includes('cut') || text.includes('croqueta')) res.push('exterior');
  if (text.includes('planta') || text.includes('solera') || text.includes('roll') || text.includes('drag') || text.includes('stop') || text.includes('maradona')) res.push('planta');
  if (text.includes('pecho')) res.push('pecho');
  if (text.includes('muslo')) res.push('muslo');
  if (text.includes('cabeza') || text.includes('cabeceo') || text.includes('header')) res.push('cabeza');
  if (text.includes('talón') || text.includes('taco') || text.includes('heel')) res.push('talon');
  
  if (res.length === 0) {
    if (p.family === 'ball_mastery') return ['planta', 'interior', 'empeine'];
    if (p.family === 'passing') return ['interior', 'empeine'];
    if (p.family === 'finishing') return ['empeine', 'interior'];
    if (p.family === 'first_touch') return ['interior', 'empeine', 'muslo'];
    if (p.family === 'turning') return ['interior', 'exterior', 'planta'];
    if (p.family === 'dribbling') return ['exterior', 'interior', 'empeine'];
    return ['interior', 'empeine'];
  }
  return res;
}

function deriveSetupSteps(p: PartialDrill): string[] {
  if (p.setupAndSteps && p.setupAndSteps.length > 0) return p.setupAndSteps;
  const eq = (p.equipment && p.equipment.length > 0) ? p.equipment.join(' y ') : 'Balón';
  const cues = p.coachingCues && p.coachingCues.length > 0 ? p.coachingCues.join(' · ') : 'Mantener centro de gravedad bajo y postura erguida';
  const obj = p.technicalObjective ? p.technicalObjective : p.name;
  return [
    `1. Configuración de Espacio: Delimitar la zona (${p.spaceRequired || '3x3m'}) utilizando ${eq}.`,
    `2. Ejecución Técnica: ${obj}. Mantener toques continuos sin perder la postura táctica.`,
    `3. Claves de Coaching: ${cues}.`
  ];
}

function deriveSetupType(p: PartialDrill): SetupType {
  if (p.setupType) return p.setupType;
  const eq = p.equipment || [];
  if (eq.includes('Pared')) return 'pared';
  if (eq.includes('Conos') || eq.includes('Conos de colores') || eq.includes('Conos numerados')) return 'conos';
  if (p.spaceRequired === 'Campo') return 'area';
  return 'balon_solo';
}

function d(p: PartialDrill): FootballDrill {
  const base = {
    technicalObjective: '', tacticalObjective: '', physicalDemand: 'Moderada',
    cognitiveDemand: 'Moderada', decisionComplexity: 2, scanningFrequency: 'Baja',
    pressureLevel: 'Sin Presión', gameRealism: 3, representativeLearningScore: 3,
    difficulty: 'Intermedio', intensity: 'Moderada', spaceRequired: 'Pequeño (3x3m)',
    equipment: ['Balón'], dominantFoot: true, weakFoot: false, bothFeet: false,
    positionRelevance: ['Todas'], footballTransfer: '', coachingCues: [], commonMistakes: [],
    progressions: [], regressions: [], estimatedTouchesPerMin: 20, decisionsPerMin: 2,
    directionChanges: 4, durationMin: 8, tags: [], ...p,
  };
  return {
    ...base,
    contactSurface: deriveSurfaces(p),
    setupAndSteps: deriveSetupSteps(p),
    setupType: deriveSetupType(p),
  } as FootballDrill;
}


