export const getTotalDrills = () => FOOTBALL_DRILL_DATABASE.length;
export const getDrillsByFamily = (family: DrillFamily) => FOOTBALL_DRILL_DATABASE.filter(d => d.family === family);
export const getDrillsByDifficulty = (difficulty: DifficultyLevel) => FOOTBALL_DRILL_DATABASE.filter(d => d.difficulty === difficulty);
export const getDrillsForWeakFoot = () => FOOTBALL_DRILL_DATABASE.filter(d => d.weakFoot);
export const searchDrills = (query: string) => {
  const q = query.toLowerCase();
  return FOOTBALL_DRILL_DATABASE.filter(d =>
    d.name.toLowerCase().includes(q) ||
    d.tags.some(t => t.includes(q)) ||
    d.technicalObjective.toLowerCase().includes(q) ||
    d.family.includes(q)
  );
};
